function progress(elapsed, totalMins) {
    return { payload: JSON.stringify({
        v:    parseFloat((elapsed / 60000).toFixed(1)),
        max:  totalMins,
        show: true
    })};
}

function modeMsg(m) { return { payload: m }; }

if (mode === 'humidity') {
    msg4.payload = 'humidity';
