            msg2.payload = 'OFF'; msg3.payload = 'OFF'; flow.set('fanON', FALSE);
        }
        return [msg, null, null, null, HIDE, HIDE, modeMsg('humidity')];
    }
    if ((humidity >= humidityThreshold) && (fanON === FALSE)) {
        msg2.payload = 'ON'; msg3.payload = 'ON'; flow.set('fanON', TRUE);
        return [msg, msg2, msg3, msg4, null, null, modeMsg('humidity')];
