        msg2.payload = 'OFF'; msg3.payload = 'OFF'; flow.set('fanON', FALSE);
        return [msg, msg2, msg3, msg4, null, null, modeMsg('humidity')];
    }
    return [msg, null, null, null, null, null, modeMsg('humidity')];

} else if (mode === 'shortTimer') {
    let startTime = flow.get('startTime');
