        startTime = Date.now(); flow.set('startTime', startTime);
        msg2.payload = 'ON'; msg3.payload = 'ON'; msg4.payload = 'shortTimer';
        flow.set('fanON', TRUE);
        return [msg, msg2, msg3, msg4, progress(0, shortTimerMins), HIDE, modeMsg('shortTimer')];
    }
    const elapsed = Date.now() - startTime;
    if (elapsed >= shortTimerMins * 60000) {
        flow.set('startTime', 0); flow.set('mode', 'humidity');
        flow.set('fanON', FALSE); flow.set('progInit', TRUE);
        msg2.payload = 'OFF'; msg3.payload = 'OFF'; msg4.payload = 'humidity';
        return [msg, msg2, msg3, msg4, HIDE, null, modeMsg('humidity')];
    }
    return [msg, null, null, null, progress(elapsed, shortTimerMins), null, modeMsg('shortTimer')];

} else if (mode === 'longTimer') {
    let startTime = flow.get('startTime');
    if (startTime === 0) {
        startTime = Date.now(); flow.set('startTime', startTime);
        msg2.payload = 'ON'; msg3.payload = 'ON'; msg4.payload = 'longTimer';
        flow.set('fanON', TRUE);
        return [msg, msg2, msg3, msg4, HIDE, progress(0, longTimerMins), modeMsg('longTimer')];
    }
    const elapsed = Date.now() - startTime;
    if (elapsed >= longTimerMins * 60000) {
        flow.set('startTime', 0); flow.set('mode', 'humidity');
        flow.set('fanON', FALSE); flow.set('progInit', TRUE);
        msg2.payload = 'OFF'; msg3.payload = 'OFF'; msg4.payload = 'humidity';
        return [msg, msg2, msg3, msg4, null, HIDE, modeMsg('humidity')];
    }
    return [msg, null, null, null, null, progress(elapsed, longTimerMins), modeMsg('longTimer')];

} else if (mode === 'off') {
