        flow.set('fanON', FALSE); flow.set('offFirstTime', FALSE);
        return [msg, msg2, msg3, msg4, HIDE, HIDE, modeMsg('off')];
    }
    return [msg, null, null, null, null, null, modeMsg('off')];
}

