function esc(value) {
    const stringValue = (value ?? '').toString();
    return /[",\n]/.test(stringValue) ? `"${stringValue.replace(/"/g, '""')}"` : stringValue;
}

function parseCsvLine(line) {
    const out = [];
    let current = '';
    let quoted = false;

    for (let index = 0; index < line.length; index++) {
        const char = line[index];
        if (quoted) {
            if (char === '"' && line[index + 1] === '"') {
                current += '"';
                index++;
            } else if (char === '"') {
                quoted = false;
            } else {
                current += char;
            }
        } else if (char === '"') {
            quoted = true;
        } else if (char === ',') {
            out.push(current);
            current = '';
        } else {
            current += char;
        }
    }

    out.push(current);
    return out;
}

